<?php
namespace davvag_events;

require_once dirname(__DIR__,2).'/lib/bootstrap.php';

final class PublicService extends Service {
    public function postExchange($req,$res) { return $this->run($req,$res,function($in){$id=$in['eventId']??'';Store::limit($id,'exchange',15);$e=Store::load($id);$t=Domain::capability($e,'rsvp',$in['credential']??'');session_regenerate_id(true);$_SESSION['davvag_events_caps'][$id]['rsvp']=['hash'=>$t['hash'],'until'=>time()+1800];return ['party'=>Domain::partyView($e,$t['reference']),'expiresIn'=>1800];},true); }
    public function getInvitation($req,$res) { return $this->run($req,$res,function($in){$e=Store::load($in['eventId']??'');Domain::gate($e);$v=Domain::publicView($e);try{$t=Domain::capability($e,'rsvp');$v['party']=Domain::partyView($e,$t['reference']);}catch(Fault $f){}$v['csrf']=Identity::csrfToken();return $v;}); }
    public function postUnlock($req,$res) { return $this->run($req,$res,function($in){Store::limit($in['eventId']??'','gate',10);$e=Store::load($in['eventId']??'');Domain::gate($e,$in);return ['unlocked'=>true];},true); }
    public function postRespond($req,$res) { return $this->run($req,$res,function($in){$id=$in['eventId']??'';Store::limit($id,'rsvp',20);$e=Store::load($id);$t=Domain::capability($e,'rsvp');$rev=$e['revision'];$op=Support::text($in['operation']??'',80,true);$key=$t['reference'].'|'.$op;foreach($e['operations'] as $o)if($o['key']===$key)return Domain::partyView($e,$t['reference']);$v=Domain::rsvp($e,$t['reference'],$in);$e['operations'][]=['key'=>$key,'at'=>Support::now()];Store::save($e,$rev,'party:'.$t['reference'],'rsvp');return $v;},true); }
    public function getSeat($req,$res) { return $this->run($req,$res,function($in){$id=$in['eventId']??'';Store::limit($id,'lookup',15);$e=Store::load($id);Domain::gate($e);$ids=[];try{$t=Domain::capability($e,'rsvp');foreach($e['guests'] as $g)if($g['partyId']===$t['reference'])$ids[]=$g['id'];}catch(Fault $f){if(empty($e['published']['nameLookup']))throw $f;$name=Support::text($in['name']??'',180,true);if(preg_match('/[%_*?]/',$name))Support::fail('LOOKUP','Use your exact invited name.');foreach($e['guests'] as $g)if(mb_strtolower($g['name'])===mb_strtolower($name))$ids[]=$g['id'];if(count($ids)!==1)Support::fail('PRIVATE_CODE','Use your personal invitation link to identify your seat.',404);}return ['seats'=>Seating::lookup($e,$ids)];}); }
    public function getCalendar($req,$res) { return $this->run($req,$res,function($in){$e=Store::load($in['eventId']??'');Domain::gate($e);$d=Domain::publicView($e)['invitation'];$escape=function($s){return str_replace(["\\","\r","\n",';',','],["\\\\",'',"\\n",'\\;','\\,'],$s);};$ics="BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//DAVVAG//Events//EN\r\nBEGIN:VEVENT\r\nUID:".$e['id'].'@'.HOST_NAME."\r\nDTSTAMP:".gmdate('Ymd\THis\Z')."\r\nDTSTART:".gmdate('Ymd\THis\Z',strtotime($d['start']))."\r\nDTEND:".gmdate('Ymd\THis\Z',strtotime($d['end']))."\r\nSUMMARY:".$escape($d['title'])."\r\nLOCATION:".$escape($d['venue'].' '.$d['address'])."\r\nDESCRIPTION:".$escape($d['message'])."\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n";return ['filename'=>'invitation.ics','content'=>$ics];}); }
}
